# construct expected output by preserving test top-left and divider, then patterned panels
N=27
out=[[4]*N for _ in range(N)]
for i in range(N): out[i][13]=1
for j in range(N): out[13][j]=1
# preserve source top-left features
for r0,r1,c0,c1,v in [(3,4,3,4,8),(3,4,5,6,7),(5,6,1,4,9),(5,6,5,6,2),(7,8,5,6,1)]:
    for r in range(r0,r1+1):
        for c in range(c0,c1+1): out[r][c]=v
# oriented symbolic tile matrices
base=[[None,8,7],[9,9,2],[None,None,1]]
import numpy as np
A=np.array(base,dtype=object)
mats={'TR':np.fliplr(A),'BL':np.flipud(A),'BR':np.flipud(np.fliplr(A))}
# target start (r,c), tile size, target tile index after transform
cases={'TR':(4,19,3,(1,0)), 'BL':(21,5,1,(1,2)), 'BR':(19,18,4,(1,0))}
for q,(tr,tc,s,(ar,ac)) in cases.items():
    mat=mats[q]
    r0=tr-ar*s; c0=tc-ac*s
    for i in range(3):
      for j in range(3):
        val=mat[i,j]
        if val is None: continue
        for dr in range(s):
          for dc in range(s):
            rr=r0+i*s+dr; cc=c0+j*s+dc
            if 14 <= rr <=26 and 14<=cc<=26 if q=='BR' else ((0<=rr<13 and 14<=cc<27) if q=='TR' else (14<=rr<27 and 0<=cc<13)):
                out[rr][cc]=int(val)
# print rows
print('\n'.join(' '.join(map(str,row)) for row in out))
